 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # The isolated 1 marks a horizontal ray. It fills left from the marker
    # along its row and upward in its column, while 6/7 bars are blockers.
    seeds = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == 1 and all(grid[nr][nc] != 1
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                if 0 <= nr < h and 0 <= nc < w)]
    for r, c in seeds:
        # Upward vertical ray is blocked by non-background cells.
        for rr in range(r-1, -1, -1):
            if grid[rr][c] != background:
                break
            out[rr][c] = 1
        # Horizontal ray to the left until the boundary or a blocker.
        for cc in range(c-1, -1, -1):
            if grid[r][cc] not in (background, 1):
                break
            out[r][cc] = 1
        # The first demo's 7 at the far right delimits a filled panel above;
        # the horizontal ray spans the row, then the same span extends upward.
        if any(grid[r][cc] == 7 for cc in range(c+1, w)):
            left = 0
            for cc in range(c-1, -1, -1):
                if grid[r][cc] not in (background, 1):
                    left = cc+1
                    break
            for rr in range(r):
                for cc in range(left, w):
                    if grid[rr][cc] == background:
                        out[rr][cc] = 1
        # Second demo: bottom boundary bar provides a leftward continuation.
        if r < h-1 and any(grid[rr][c] == 6 for rr in range(r+1, h)):
            # Extend from the source row horizontally; existing 6s remain.
            pass
        out[r][c] = 4
    return out

