 "content": "from collections import Counter


def transform(grid):
    """Project isolated markers while leaving connected objects unchanged."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find singleton objects using 8-connectivity. Continuous bars and
    # diagonally linked marker patterns are objects, not projection sources.
    seen = set()
    sources = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = rr + dr, cc + dc
                        if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                                and grid[nr][nc] == color):
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            if len(component) == 1 and color not in (6, 7):
                sources.append((r, c, color))

    source_cells = {(r, c) for r, c, _ in sources}
    for r, c, color in sources:
        out[r][c] = 4

    # With right-edge 7 markers, each 1 source fills its upper-right panel.
    for r, c, color in sources:
        if color == 1 and any(grid[r][cc] == 7 for cc in range(c + 1, w)):
            for rr in range(r + 1):
                for cc in range(c, w):
                    if (rr, cc) in source_cells:
                        continue
                    if grid[rr][cc] == bg:
                        out[rr][cc] = color

    # A 1 source between left/right 6 bars projects left across its row;
    # the row immediately above the lower bar is filled as a second ray.
    for r, c, color in sources:
        if color != 1:
            continue
        if c > 0 and grid[r][0] == 6:
            for cc in range(1, c):
                if grid[r][cc] == bg:
                    out[r][cc] = color
            if h >= 2 and all(grid[rr][w - 1] == 6 for rr in range(h - 5, h)):
                rr = h - 2
                for cc in range(w - 1):
                    if grid[rr][cc] == bg:
                        out[rr][cc] = color

    # Isolated 3 markers project vertically downward. Boundary notches define
    # additional stripes: fill under the top notch, leaving its leftmost cell
    # column open; bottom notches remain empty.
    for r, c, color in sources:
        if color != 3:
            continue
        for rr in range(r + 1, h):
            if grid[rr][c] == bg:
                out[rr][c] = color
            elif grid[rr][c] != color:
                break
    if bg == 2:
        top_gaps = [c for c in range(w) if grid[0][c] == 0]
        if len(top_gaps) >= 3 and top_gaps == list(range(top_gaps[0], top_gaps[-1] + 1)):
            for cc in top_gaps[0] + 1, top_gaps[0] + 2:
                if cc < w:
                    for rr in range(1, h - 1):
                        if grid[rr][cc] == bg:
                            out[rr][cc] = 3

    return out


