    # Demo 1
    d1 = [[7] + [0] * 22, [7] + [0] * 22,
          [0, 1] + [0] * 20 + [7], [0] * 17 + [1] + [0] * 5 + [7],
          [0] * 23, [0] * 23]
    e1 = [[7] + [1] * 22, [7] + [1] * 22,
          [0, 4] + [1] * 20 + [7], [0] * 17 + [4] + [1] * 5 + [7],
          [0] * 23, [0] * 23]

    # Demo 2
