    for rr in range(7, 12):
        d2[rr][10] = 6
    d2[5][9] = 1
    e2 = [[0] * 11 for _ in range(12)]
    for rr in range(2, 6):
        e2[rr][0] = 6
    for rr in range(7, 12):
        e2[rr][10] = 6
    e2[5] = [6] + [1] * 8 + [4, 0]
    e2[10] = [1] * 10 + [6]

    # Demo 3
    d3 = [[2] * 18 for _ in range(8)]
    d3[0] = [2] * 15 + [0] * 3
    d3[1][8] = 3
    d3[4][7] = 3
    d3[7] = [2] * 6 + [0] * 3 + [2] * 9
    e3 = [row[:] for row in d3]
    e3[1][8] = 4
    e3[4][7] = 4
    for rr in range(2, 7):
        e3[rr][8] = 3
    for rr in range(5, 7):
        e3[rr][7] = 3
    for rr in range(1, 7):
        for cc in (16, 17):
            e3[rr][cc] = 3

    assert transform(d1) == e1
    assert transform(d2) == e2
    assert transform(d3) == e3
    test = [[9] * 17 + [1] * 5, [9] * 22,
            [9, 9, 3] + [9] * 19, [3, 9, 9, 3] + [9] * 18,
            [9, 3, 9, 9, 3] + [9] * 17, [9] * 22,
            [1] * 5 + [9] * 17]
    for row in transform(test):
        print(*row)
    print('all demonstrations reproduced')
