def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in seeds:
        out[r][c] = 4
        for rr in range(r + 1, h):
            if grid[rr][c] != bg:
                break
            out[rr][c] = 3

    # Edge bars project the seed color inward, leaving the leading endpoint
    # of each bar unchanged, as in the boundary-bar examples.
    top = [c for c, value in enumerate(grid[0]) if value != bg]
    if len(top) > 1 and all(grid[0][c] == grid[0][top[0]] for c in top):
        for c in top[1:]:
            for r in range(1, h - 1):
                if grid[r][c] == bg:
                    out[r][c] = 3
    bottom = [c for c, value in enumerate(grid[h - 1]) if value != bg]
    if len(bottom) > 1 and all(grid[h - 1][c] == grid[h - 1][bottom[0]] for c in bottom):
        for c in bottom[1:]:
            for r in range(h - 2, 0, -1):
                if grid[r][c] == bg:
                    out[r][c] = 3
    return out


