 "content": "from collections import Counter


def _edge_runs(values, bg):
    runs = []
    i = 0
    while i < len(values):
        if values[i] == bg:
            i += 1
            continue
        color = values[i]
        start = i
        while i + 1 < len(values) and values[i + 1] == color:
            i += 1
        runs.append((color, start, i))
        i += 1
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Opposite boundary bars are matching rulers. A singleton marker whose
    # coordinate falls within one bar activates the corresponding offset on
    # both bars. Rays grow inward from each active boundary point and stop at
    # the first original non-background cell (including a marker).
    side_pairs = []
    top = _edge_runs(grid[0], bg)
    bottom = _edge_runs(grid[h - 1], bg)
    for a in top:
        for b in bottom:
            if a[0] == b[0]:
                side_pairs.append(("horizontal", a, b))

    left = _edge_runs([grid[r][0] for r in range(h)], bg)
    right = _edge_runs([grid[r][w - 1] for r in range(h)], bg)
    for a in left:
        for b in right:
            if a[0] == b[0]:
                side_pairs.append(("vertical", a, b))

    for axis, a, b in side_pairs:
        boundary_color = a[0]
        markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] != bg and grid[r][c] != boundary_color]
        for r, c, color in markers:
            pos = c if axis == "horizontal" else r
            if a[1] <= pos <= a[2]:
                offset, source_side = pos - a[1], 0
            elif b[1] <= pos <= b[2]:
                offset, source_side = pos - b[1], 1
            else:
                continue
            out[r][c] = 4
            for side, run in ((0, a), (1, b)):
                target_pos = run[1] + offset
                if target_pos > run[2]:
                    continue
                if axis == "horizontal":
                    edge_row = 0 if side == 0 else h - 1
                    step = 1 if side == 0 else -1
                    rr = edge_row + step
                    while 0 <= rr < h - 1:
                        if grid[rr][target_pos] != bg:
                            break
                        out[rr][target_pos] = color
                        rr += step
                else:
                    edge_col = 0 if side == 0 else w - 1
                    step = 1 if side == 0 else -1
                    cc = edge_col + step
                    while 0 <= cc < w - 1:
                        if grid[target_pos][cc] != bg:
                            break
                        out[target_pos][cc] = color
                        cc += step
    return out


if __name__ == "__main__":
    test = [[9] * 17 + [1] * 5, [9] * 22,
            [9, 9, 3] + [9] * 19,
            [3, 9, 9, 3] + [9] * 18,
            [9, 3, 9, 9, 3] + [9] * 17,
            [9] * 22, [1] * 5 + [9] * 17]
    result = transform(test)
    assert len(result) == 7 and all(len(row) == 22 for row in result)
    for row in result:
        print(*row)
    print("verified dimensions")
  ",
 "cross_profile": false
}

