# Candidate: preserve 1 bars, recolor each 3 to 4, draw vertical 3 rays downward,
# and project the two background cells adjoining each boundary bar inward.
grid = [[9]*17 + [1]*5,
        [9]*22,
        [9,9,3] + [9]*19,
        [3,9,9,3] + [9]*18,
        [9,3,9,9,3] + [9]*17,
        [9]*22,
        [1]*5 + [9]*17]
h, w = len(grid), len(grid[0])
out = [row[:] for row in grid]
# Marker vertical rays downward, stopping at any non-background input cell.
for r in range(h):
    for c in range(w):
        if grid[r][c] == 3:
            out[r][c] = 4
            for rr in range(r+1, h):
                if grid[rr][c] != 9:
                    break
                out[rr][c] = 3
# Boundary-adjacent two-cell projections: top bar c17..21 => c15,16 down;
# bottom bar c0..4 => c5,6 up.
for rr in range(1, h):
    for c in (15,16):
        if grid[rr][c] == 9: out[rr][c] = 3
for rr in range(0, h-1):
    for c in (5,6):
        if grid[rr][c] == 9: out[rr][c] = 3
print('shape', h, w, 'rows', [len(row) for row in out])
for row in out: print(' '.join(map(str,row)))

