 "content": "from collections import Counter


def runs(values, bg):
    result = []
    i = 0
    while i < len(values):
        if values[i] == bg:
            i += 1
            continue
        color, start = values[i], i
        while i + 1 < len(values) and values[i + 1] == color:
            i += 1
        result.append((color, start, i))
        i += 1
    return result


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and (r, c) not in
             {(rr, cc) for rr in range(h) for cc in range(w)
              if (rr in (0, h - 1) or cc in (0, w - 1))}]

    # Opposing equal edge bars carry aligned offsets. Each non-background
    # marker within a bar's span projects toward that edge; its aligned offset
    # on the opposite bar projects inward as a parallel ray.
    pairs = []
    top = runs(grid[0], bg)
    bottom = runs(grid[h - 1], bg)
    for a in top:
        for b in bottom:
            if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                pairs.append(("horizontal", a, b))
    left = runs([grid[r][0] for r in range(h)], bg)
    right = runs([grid[r][w - 1] for r in range(h)], bg)
    for a in left:
        for b in right:
            if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                pairs.append(("vertical", a, b))

    for axis, a, b in pairs:
        boundary_color = a[0]
        for r, c, color in marks:
            pos = c if axis == "horizontal" else r
            if a[1] <= pos <= a[2]:
                side, offset = 0, pos - a[1]
            elif b[1] <= pos <= b[2]:
                side, offset = 1, pos - b[1]
            else:
                continue
            out[r][c] = 4

            # Marker casts a ray to the boundary bar it aligns with.
            if axis == "horizontal":
                edge_r, step = (0, -1) if side == 0 else (h - 1, 1)
                rr = r + step
                while 0 <= rr < h and rr != edge_r:
                    if grid[rr][c] == bg:
                        out[rr][c] = color
                    rr += step
            else:
                edge_c, step = (0, -1) if side == 0 else (w - 1, 1)
                cc = c + step
                while 0 <= cc < w and cc != edge_c:
                    if grid[r][cc] == bg:
                        out[r][cc] = color
